@dataclass
class DetectionBoundingBox:
    x_min: int
    y_min: int
    x_max: int
    y_max: int

    def to_tuple(self) -> tuple[int, int, int, int]:
        return (self.x_min, self.y_min, self.x_max, self.y_max)

@dataclass
class Detection:
    img_path: str
    label: str # YOLO class name
    label_id: int # YOLO class index
    BoundingBox : DetectionBoundingBox

    def __post_init__(self):
        pass

    @property
    def description(self) -> str:
        x_min, y_min, x_max, y_max = self.BoundingBox.x_min, self.BoundingBox.y_min, self.BoundingBox.x_max, self.BoundingBox.y_max
        return f"  {self.label} ({self.label_id}): ({int(x_min)}, {int(y_min)}) - ({int(x_max)}, {int(y_max)})"

    @property
    def image(self) -> "PILImage.Image":
        return PILImage.open(self.img_path)

    @property
    def cropped_image(self) -> "PILImage.Image":
        image = PILImage.open(self.img_path)
        x_min, y_min, x_max, y_max = self.BoundingBox.x_min, self.BoundingBox.y_min, self.BoundingBox.x_max, self.BoundingBox.y_max
        return image.crop((x_min, y_min, x_max, y_max))
    
    @property
    def image_bytes(self) -> bytes:
        from io import BytesIO

        buffer = BytesIO()
        self.image.save(buffer, format="JPEG")
        return buffer.getvalue()

    @property
    def cropped_bytes(self) -> bytes:
        from io import BytesIO

        buffer = BytesIO()
        self.cropped_image.save(buffer, format="JPEG")
        return buffer.getvalue()


def detect_objects_in_image(img_path, model: YOLO, confidence: float = 0.7, debug_prn: bool = False) -> list[Detection]:

    results = model(str(img_path), conf=confidence, verbose=False)

    detected_objects  = []

    for result in results:
        for detection in result.boxes:
            image_detect = Detection(
                img_path=img_path,
                BoundingBox=DetectionBoundingBox(
                    x_min=int(detection.xyxy[0][0]),
                    y_min=int(detection.xyxy[0][1]),
                    x_max=int(detection.xyxy[0][2]),
                    y_max=int(detection.xyxy[0][3])
                ),
                label_id=int(detection.cls[0]),
                label=model.names[int(detection.cls[0])]
            )
            detected_objects.append(image_detect)

            if debug_prn:
                print(image_detect.description)

    return detected_objects


# %% ../tutorials/04-detect.ipynb #c9573b10
@dataclass
class AnnotatedImage:
    img_path : str
    model : YOLO
    detections: list[Detection] = None

    @property
    def image(self) -> PILImage.Image:
        return PILImage.open(self.img_path).convert("RGB")

    @classmethod
    def from_path(cls, img_path: str, model: YOLO, confidence: float = 0.7, debug_prn : bool = False) -> "AnnotatedImage":

        img = cls(img_path=img_path, model=model)

        img.get_detections(model=model, confidence=confidence, debug_prn=debug_prn)

        return img

    def get_detections(self, model: YOLO, confidence: float = 0.7, debug_prn: bool = False) -> list[Detection]:

        self.detections = detect_objects_in_image(img_path = self.img_path, model=model, confidence=confidence, debug_prn=debug_prn)

        return self.detections

    @property
    def image_w_labels(self) -> PILImage.Image:
        annotated = self.image.copy()
        draw = ImageDraw.Draw(annotated)

        for detection in self.detections:
            x_min, y_min, x_max, y_max = detection.BoundingBox.to_tuple()
            draw.rectangle([x_min, y_min, x_max, y_max], outline="red", width=2)
            draw.text((x_min, y_min), detection.label, fill="red")

        return annotated

